# Generators for the desktop: sway, waybar, wofi, mako, termite.
# Sourced by theme-switch after a palette has been loaded.

# Write stdin to a file atomically (tmp file + rename).
write_file() {
	local dest="$1" tmp
	mkdir -p "$(dirname "$dest")"
	tmp="$(mktemp "${dest}.XXXXXX")"
	cat >"$tmp"
	mv -f "$tmp" "$dest"
}

gen_sway() {
	write_file "$HOME/.config/sway/theme" <<EOF
# Generated by theme-switch ($THEME_NAME) — do not edit, edit the palette instead.
# class                 border     backgr.    text     indicator  child_border
client.focused          $BG0 $BG0 $FG0 $ACCENT2 $ACCENT2
client.focused_inactive $BG1 $BG1 $FG0 $BG3 $BG3
client.unfocused        $BG2 $BG2 $FG0 $BG3 $BG3
client.urgent           $RED $RED $FG2 $ORANGE $ORANGE

$(sway_wallpaper)
EOF
}

# WALLPAPER is an image path, or a "#rrggbb" color for a plain background.
sway_wallpaper() {
	if [[ "$WALLPAPER" == \#* ]]; then
		printf 'output * bg %s solid_color' "$WALLPAPER"
	else
		printf 'output * bg "%s" fill' "$WALLPAPER"
	fi
}

# Base16-style names used by the waybar and wofi stylesheets.
css_colors() {
	cat <<EOF
/* Generated by theme-switch ($THEME_NAME) — do not edit, edit the palette instead. */
@define-color base10 $BG0;
@define-color base00 $BG0;
@define-color base01 $BG1;
@define-color base02 $BG2;
@define-color base03 $BG3;
@define-color base04 $FG0;
@define-color base05 $FG1;
@define-color base06 $FG2;
@define-color base07 $ACCENT;
@define-color base08 $CYAN;
@define-color base09 $MUTED;
@define-color base0A $BLUE;
@define-color base0B $RED;
@define-color base0B-light $RED;
@define-color base0C $ORANGE;
@define-color base0D $YELLOW;
@define-color base0E $GREEN;
@define-color base0F $PURPLE;
EOF
}

gen_waybar() { css_colors | write_file "$HOME/.config/waybar/colors.css"; }
# wofi doesn't resolve @import, so its stylesheet is the palette followed by
# the hand-written rules in style.base.css.
gen_wofi() {
	local base="$HOME/.config/wofi/style.base.css"
	[[ -f "$base" ]] || { warn "wofi style.base.css not found, skipping"; return 0; }
	{ css_colors; echo; cat "$base"; } | write_file "$HOME/.config/wofi/style.css"
}

gen_mako() {
	write_file "$HOME/.config/mako/config" <<EOF
# Generated by theme-switch ($THEME_NAME) — do not edit, edit the palette instead.
# Read \`man 5 mako\` for a complete reference.

font=GeistMono Nerd Font Propo 11
background-color=$BG0
text-color=$FG1
border-color=$ACCENT2
progress-color=over $BG3

width=360
padding=10
margin=10
border-size=2
border-radius=10
icons=1
max-icon-size=48
max-visible=5
layer=overlay
anchor=top-right

default-timeout=5000
ignore-timeout=0

[urgency=low]
border-color=$BG3
text-color=$FG0

[urgency=critical]
border-color=$RED
default-timeout=0
EOF
}

# swaylock takes colors as rrggbb[aa] without the '#'.
hex() { printf '%s%s' "${1#\#}" "${2:-}"; }

gen_swaylock() {
	write_file "$HOME/.config/swaylock/config" <<EOF
# Generated by theme-switch ($THEME_NAME) — do not edit, edit the palette instead.
# Lock with \$mod+Escape. Read \`man swaylock\` for a complete reference.

$( [[ "$WALLPAPER" == \#* ]] || printf 'image=%s\nscaling=fill' "$WALLPAPER" )
color=$( [[ "$WALLPAPER" == \#* ]] && hex "$WALLPAPER" || hex "$BG0" )

font=GeistMono Nerd Font Propo
font-size=24
indicator-radius=110
indicator-thickness=10
show-failed-attempts
ignore-empty-password

# Idle
inside-color=$(hex "$BG0" cc)
ring-color=$(hex "$ACCENT2")
line-color=00000000
separator-color=00000000
text-color=$(hex "$FG1")
key-hl-color=$(hex "$ACCENT")
bs-hl-color=$(hex "$ORANGE")

# Checking the password
inside-ver-color=$(hex "$BG0" cc)
ring-ver-color=$(hex "$BLUE")
line-ver-color=00000000
text-ver-color=$(hex "$FG1")

# Wrong password
inside-wrong-color=$(hex "$BG0" cc)
ring-wrong-color=$(hex "$RED")
line-wrong-color=00000000
text-wrong-color=$(hex "$RED")

# Input cleared
inside-clear-color=$(hex "$BG0" cc)
ring-clear-color=$(hex "$YELLOW")
line-clear-color=00000000
text-clear-color=$(hex "$FG1")

# Caps Lock on
caps-lock-key-hl-color=$(hex "$YELLOW")
caps-lock-bs-hl-color=$(hex "$ORANGE")
inside-caps-lock-color=$(hex "$BG0" cc)
ring-caps-lock-color=$(hex "$YELLOW")
line-caps-lock-color=00000000
text-caps-lock-color=$(hex "$YELLOW")
EOF
}

# swaynag: the exit prompt ($mod+Shift+e, waybar power button) uses
# [warning]; sway's own config-error bar uses [error].
swaynag_type() {
	local name="$1" accent="$2"
	cat <<EOF
[$name]
background=$(hex "$BG0")
text=$(hex "$FG1")
border=$(hex "$accent")
border-bottom=$(hex "$accent")
border-bottom-size=3
button-background=$(hex "$BG1")
button-text=$(hex "$FG1")
details-background=$(hex "$BG1")

EOF
}

gen_swaynag() {
	{
		cat <<EOF
# Generated by theme-switch ($THEME_NAME) — do not edit, edit the palette instead.
font=GeistMono Nerd Font Propo 11
message-padding=8
button-padding=6
button-border-size=2
button-gap=10
button-margin-right=6

EOF
		swaynag_type warning "$ORANGE"
		swaynag_type error "$RED"
	} | write_file "$HOME/.config/swaynag/config"
}

# Termite: replace only the [colors] section and the [hints] colors,
# keep every other option the user set.
gen_termite() {
	local conf="$HOME/.config/termite/config" colors i
	[[ -f "$conf" ]] || { warn "termite config not found, skipping"; return 0; }

	colors="cursor = $TERM_CURSOR
cursor_foreground = $BG0

foreground = $TERM_FG
foreground_bold = $TERM_FG
background = $TERM_BG

highlight = $BG3
"
	for i in "${!ANSI[@]}"; do
		colors+="$(printf 'color%-2s = %s' "$i" "${ANSI[$i]}")"$'\n'
	done

	awk -v colors="$colors" -v fg="$FG0" -v bg="$BG1" -v afg="$BG0" -v abg="$CYAN" -v border="$BG3" '
		/^\[colors\]/ { print; print colors; skip = 1; next }
		/^\[/         { skip = 0; hints = ($0 ~ /^\[hints\]/) }
		skip          { next }
		hints && /^foreground *=/        { print "foreground = " fg; next }
		hints && /^background *=/        { print "background = " bg; next }
		hints && /^active_foreground *=/ { print "active_foreground = " afg; next }
		hints && /^active_background *=/ { print "active_background = " abg; next }
		hints && /^border *=/            { print "border = " border; next }
		{ print }
	' "$conf" | write_file "$conf"
}

reload_desktop() {
	# Reloading sway also restarts waybar (it is sway's bar command), which picks
	# up the new colors. Don't also signal waybar: a USR2 that reaches the new
	# instance before it installs its handler kills it.
	swaymsg reload >/dev/null 2>&1 || warn "sway reload failed"
	makoctl reload 2>/dev/null || warn "mako reload failed"
	pkill -SIGUSR1 -x termite 2>/dev/null || true # termite reloads its config on USR1
}
